type Person = {
  name: Str;
  age: Int;
}

fn Person.introduce(self) {
  io.println("Hi, I'm " + name + "!");
}

fn Person.birthday(self) {
  age = age + 1;
}

fn main() -> Int {
  let me = Person{ name: "Sam", age: 14 };
  me.introduce();
  me.birthday();
  io.println(me.age);
  return 0;
}
